import{_ as i,l as o,o as e,c as n,v as t,p as s,x as l,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"视觉指令数据","description":"","frontmatter":{"title":"视觉指令数据","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/visual-instruction-data.md","filePath":"llm/visual-instruction-data.md","lastUpdated":1789023840000}'),h={name:"llm/visual-instruction-data.md"};function A(E,a,u,m,_,B){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="视觉指令数据" tabindex="-1">视觉指令数据 <a class="header-anchor" href="#视觉指令数据" aria-label="Permalink to &quot;视觉指令数据&quot;">​</a></h1><div class="epigraph"><p>投影器只把格子送进词槽。模型会不会按指令谈图，取决于第二阶段看见过什么样的「用户问、助手答」。</p><footer>—— Liu 等 Visual Instruction Tuning（LLaVA）；对照 [投影器](/llm/llava-projector) 的两阶段</footer></div><p><a href="/llm/2d-rope">上一课</a>把二维格子写进注意力相位。<a href="/llm/clip">CLIP</a> 与 <a href="/llm/vit-as-encoder">ViT</a> 只保证图可被编码。缺口是语言动作：描述、列点、听约束、拒答。后课幻觉默认你已知道——指令数据会教模型「开口说物体」，也会教它说过头。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>图文对只监督短标题。<a href="/llm/llava-projector">LLaVA 投影器</a> 第一阶段把 \\(H_v\\) 对齐到能续写 caption；没有第二阶段，LLM 仍按纯文本对话先验说话，图前缀像一根未接线的电缆。学术 VQA 是单轮短答案，覆盖不了「按用户措辞谈这张图」。</p><p>LLaVA 的做法是把 COCO 的标题与框交给 GPT-4（当时只吃文本）合成多轮对话、细描述与复杂推理，约 158K。教师看不见像素，空间关系来自框坐标；标题没写的颜色、细字、未标物体，合成里也不会出现——这是后课物体幻觉的数据源，不是投影器算错。</p><p><span class="marginnote">指令模板必须与部署一致：图在前还是插在问题中、角色标记、是否要求先看图再答。槽位一变，第二阶段学到的「如何谈图」会错位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据三类要分列，不要混成一个「视觉 SFT」桶。对齐用图–标题；指令用对话/推理；定位、OCR、GUI 必须另加带坐标或转写的监督，合成对话补不了。验收看：是否听否定（「不要列举」）、是否跟指代（「左边那个」）、是否在无物体时拒答。不要用 CLIP 检索分选指令数据配比。</p>',9)),(e(),s(c,null,{default:l(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E5%9B%BE%E6%96%87%E5%AF%B9%22%5D%20--%3E%20ALIGN%5B%22%E5%8F%AA%E8%AE%AD%E6%8A%95%E5%BD%B1%E5%AF%B9%E9%BD%90%22%5D%0A%20%20INS%5B%22%E5%90%88%E6%88%90%E6%88%96%E4%BA%BA%E5%B7%A5%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20SFT%5B%22%E6%8C%87%E4%BB%A4%E5%BE%AE%E8%B0%83%22%5D%0A%20%20ALIGN%20--%3E%20SFT%0A%20%20SFT%20--%3E%20ACT%5B%22%E8%AF%AD%E8%A8%80%E5%8A%A8%E4%BD%9C%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>第二阶段把视觉前缀当作可被查询的键值，语言损失从回答词反传到投影（以及解冻的 LLM）。模型学会的是「看见这些 patch 时，助手分布该长什么样」，不是像素级绑定。因此同一套 <a href="/llm/clip">CLIP</a> 骨干，换指令配比会换能力：多描述少定位，就擅长段落、弱于框。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>合成指令便宜，但教师偏见与标题覆盖是天花板。下一课用 POPE 把「说有物体」从真看见里拆开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视觉指令数据把格子对齐到语言动作；标题对不够。</li><li>教师若看不见像素，未写入标题的东西不会进入监督。</li><li>模板与任务配比决定会哪种谈法，不是投影器深度。</li><li>出处：Liu 等 LLaVA；投影路径见投影器课。</li></ul>',6))])}const L=i(h,[["render",A]]);export{T as __pageData,L as default};
